#!/usr/bin/env python3
"""Remove only obsolete, unreleased Gallery prototype preference migrations."""
from pathlib import Path
import hashlib,json
p=Path("gallery/Gallery-current.html")
raw=p.read_bytes()
assert len(raw)==6952404 and hashlib.sha256(raw).hexdigest()=="8cd1f045580b32d98d5d70e2da6e0a9f2dcac744c7a011f2ff850d1a6ddc45fb","STOP: GitHub baseline mismatch"
s=raw.decode("utf-8")
for a,b in json.loads("[[\"/* Initial player volume: remember changes between sessions, or use a fixed starting value.\\n   The default is 70%; 0%/mute never overwrites the last audible volume.\\n   All of this remains local to the HTML prototype until the native player is connected. */\",\"/* Initial player volume uses the Gallery default or the user's starting value.\\n   The default is 70%; session volume is not a saved starting preference. */\"],[\"   /* Keep old fixed preferences when upgrading the experiment. Do not migrate\\n      Remember last volume: there is deliberately no cross-session memory now. */\\n\",\"\"],[\"mode:saved.mode==='user'||saved.mode==='fixed'?'user':'gallery'\",\"mode:saved.mode==='user'?'user':'gallery'\"],[\"localStorage.getItem('gallery.font')||localStorage.getItem('gallery.layoutExperimentA.font')\",\"localStorage.getItem('gallery.font')\"],[\"function subtitleNearestPreset(effect,value,size){\\n const presets=Object.keys(SUBTITLE_EFFECT_PRESETS[effect]||{});\\n return presets.reduce((best,id)=>Math.abs(subtitlePresetValue(effect,id,size)-value)<Math.abs(subtitlePresetValue(effect,best,size)-value)?id:best,'normal');\\n}\\n\",\"\"],[\"function normalizeSubtitleSize(size){\\n if(typeof size==='string' && SUBTITLE_SIZES.some(entry=>entry.id===size))return size;\\n // Migrate saved v82–v92 numeric sizes to the nearest named preset.\\n if(typeof size==='number' && Number.isFinite(size))\\n  return SUBTITLE_SIZES.reduce((best,entry)=>Math.abs(entry.reference-size)<Math.abs(best.reference-size)?entry:best).id;\\n return SUBTITLE_DEFAULTS.size;\\n}\\n\",\"function normalizeSubtitleSize(size){\\n return typeof size==='string' && SUBTITLE_SIZES.some(entry=>entry.id===size)?size:SUBTITLE_DEFAULTS.size;\\n}\\n\"],[\"function readSubtitlePrefs(){\\n try{\\n  const raw=JSON.parse(localStorage.getItem('gallery.subtitlePreferences')||localStorage.getItem('gallery.layoutExperimentA.subtitlePreview')||'{}');\\n  if(!raw||typeof raw!=='object')return {...SUBTITLE_DEFAULTS};\\n  const v={...SUBTITLE_DEFAULTS};\\n  if(Object.hasOwn(SUBTITLE_FONTS,raw.font))v.font=raw.font;\\n  v.size=normalizeSubtitleSize(raw.size);\\n  for(const [key,min,max] of [['outline',0,6],['shadow',0,10]])\\n   if(Number.isFinite(raw[key]))v[key]=Math.max(min,Math.min(max,Math.round(raw[key]*2)/2));\\n  v.outline=Math.min(v.outline,maximumSubtitleOutline(v.size));\\n  if(Number.isFinite(raw.boxOpacity))v.boxOpacity=Math.max(0,Math.min(100,Math.round(raw.boxOpacity/5)*5));\\n  for(const key of ['color','outlineColor','shadowColor','boxColor'])\\n   if(/^#[0-9a-fA-F]{6}$/.test(raw[key]||''))v[key]=raw[key].toLowerCase();\\n   // Legacy copies stored only a hex value. Treat the former #FFFFFF default\\n   // as the new Soft White preset; preserve all other user-selected colors.\\n   const validHex=c=>typeof c==='string' && /^#[0-9a-fA-F]{6}$/.test(c);\\n   if(['white','yellow','custom'].includes(raw.colorMode)){\\n    v.colorMode=raw.colorMode;\\n    if(validHex(raw.customColor))v.customColor=raw.customColor.toLowerCase();\\n    else if(v.colorMode==='custom' && validHex(raw.color))v.customColor=raw.color.toLowerCase();\\n   }else if(validHex(raw.color)){\\n    const previous=raw.color.toLowerCase();\\n    if(previous==='#ffe066')v.colorMode='yellow';\\n    else if(!['#ffffff','#f5f5f5','#f8f8f8'].includes(previous)){\\n     v.colorMode='custom';v.customColor=previous;\\n    }\\n   }\\n   // Older experiments did not store whether Custom had ever been chosen.\\n   // A nondefault saved swatch or a previously selected Custom mode implies yes.\\n   v.customColorSet=typeof raw.customColorSet==='boolean'\\n    ?raw.customColorSet\\n    :(v.colorMode==='custom'||v.customColor!==SUBTITLE_DEFAULTS.customColor);\\n   v.color=v.colorMode==='custom'?v.customColor:SUBTITLE_TEXT_COLOR_PRESETS[v.colorMode];\\n   if(!Object.hasOwn(raw,'shadowColor'))v.shadowColor=v.outlineColor;\\n  if(['outline','shadow','box','none'].includes(raw.effect))v.effect=raw.effect;\\n  // Migrate the separate background selector from v95 to the unified style.\\n  // When an old background was enabled, preserve that explicit choice.\\n  if(['solid','translucent'].includes(raw.background) && !['box','none'].includes(raw.effect)){\\n   v.effect='box';v.boxOpacity=raw.background==='solid'?100:60;\\n  }\\n  // Existing A8 slider settings are mapped to their nearest A9 named preset.\\n  for(const [effect,key,presetKey] of [['outline','outline','outlinePreset'],['shadow','shadow','shadowPreset'],['box','boxOpacity','boxPreset']]){\\n   const saved=raw[presetKey];\\n   v[presetKey]=saved==='max'?'strong':['light','normal','strong'].includes(saved)?saved:subtitleNearestPreset(effect,v[key],v.size);\\n  }\\n  assignSubtitlePresetNumbers(v);\\n  return v;\\n }catch{return {...SUBTITLE_DEFAULTS};}\\n}\\n\",\"function readSubtitlePrefs(){\\n try{\\n  const raw=JSON.parse(localStorage.getItem('gallery.subtitlePreferences')||'{}');\\n  if(!raw||typeof raw!=='object'||Array.isArray(raw))return {...SUBTITLE_DEFAULTS};\\n  const v={...SUBTITLE_DEFAULTS};\\n  const validHex=c=>typeof c==='string' && /^#[0-9a-fA-F]{6}$/.test(c);\\n  if(Object.hasOwn(SUBTITLE_FONTS,raw.font))v.font=raw.font;\\n  v.size=normalizeSubtitleSize(raw.size);\\n  for(const key of ['outlineColor','shadowColor','boxColor','customColor'])\\n   if(validHex(raw[key]))v[key]=raw[key].toLowerCase();\\n  if(['white','yellow','custom'].includes(raw.colorMode))v.colorMode=raw.colorMode;\\n  if(typeof raw.customColorSet==='boolean')v.customColorSet=raw.customColorSet;\\n  v.color=v.colorMode==='custom'?v.customColor:SUBTITLE_TEXT_COLOR_PRESETS[v.colorMode];\\n  if(['outline','shadow','box','none'].includes(raw.effect))v.effect=raw.effect;\\n  for(const key of ['outlinePreset','shadowPreset','boxPreset'])\\n   if(['light','normal','strong'].includes(raw[key]))v[key]=raw[key];\\n  assignSubtitlePresetNumbers(v);\\n  return v;\\n }catch{return {...SUBTITLE_DEFAULTS};}\\n}\\n\"]]"):
    assert s.count(a)==1,(a[:100],s.count(a))
    s=s.replace(a,b)
p.write_bytes(s.encode("utf-8"))
tests=Path("gallery/tests/test_player_settings_regression.py")
t=tests.read_text(encoding="utf-8")
a,b=json.loads("[\" # A routed in-memory page provides a real storage origin without network access.\\n legacy=browser.new_page(viewport={\\\"width\\\":1200,\\\"height\\\":850})\\n legacy.route(\\\"https://gallery-audit.invalid/**\\\",lambda route:route.fulfill(status=200,content_type=\\\"text/html\\\",body=html))\\n legacy.goto(\\\"https://gallery-audit.invalid/\\\")\\n legacy.evaluate(\\\"\\\"\\\"() => localStorage.setItem('gallery.subtitlePreferences', JSON.stringify({size:'normal',outlinePreset:'max',shadowPreset:'max',boxPreset:'max',colorMode:'custom',customColor:'#123456',customColorSet:true}))\\\"\\\"\\\")\\n migrated=legacy.evaluate(\\\"readSubtitlePrefs()\\\")\\n check([migrated[k] for k in (\\\"outlinePreset\\\",\\\"shadowPreset\\\",\\\"boxPreset\\\")]==[\\\"strong\\\"]*3,\\\"Legacy Max migrates to High\\\")\\n check([migrated[k] for k in (\\\"outline\\\",\\\"shadow\\\",\\\"boxOpacity\\\")]==[5.5,10,100],\\\"Former Max strength preserved\\\")\\n check(migrated[\\\"customColor\\\"]==\\\"#123456\\\" and migrated[\\\"customColorSet\\\"],\\\"Saved custom color survives migration\\\")\\n legacy.close()\\n\",\" # Current preferences round-trip and invalid values fall back to defaults.\\n prefs=browser.new_page(viewport={\\\"width\\\":1200,\\\"height\\\":850})\\n prefs.route(\\\"https://gallery-audit.invalid/**\\\",lambda route:route.fulfill(status=200,content_type=\\\"text/html\\\",body=html))\\n prefs.goto(\\\"https://gallery-audit.invalid/\\\")\\n prefs.evaluate(\\\"\\\"\\\"() => {\\n  Object.assign(subtitlePrefs,{font:'inter',size:'large',effect:'shadow',outlinePreset:'strong',shadowPreset:'light',boxPreset:'strong',colorMode:'custom',customColor:'#123456',customColorSet:true,outlineColor:'#abcdef',shadowColor:'#334455',boxColor:'#556677'});\\n  assignSubtitlePresetNumbers(subtitlePrefs);\\n  subtitlePrefs.color=subtitlePrefs.customColor;\\n  persistSubtitlePrefs();\\n  Object.assign(galleryVolumePreferences,{mode:'user',preferred:35,precision:'fine'});\\n  saveGalleryVolumePreferences();\\n  localStorage.setItem('gallery.font','inter');\\n  localStorage.setItem('gallery.softFuturistic.theme','glacier');\\n }\\\"\\\"\\\")\\n prefs.reload()\\n saved=prefs.evaluate(\\\"subtitlePrefs\\\")\\n check([saved[k] for k in (\\\"font\\\",\\\"size\\\",\\\"effect\\\",\\\"outlinePreset\\\",\\\"shadowPreset\\\",\\\"boxPreset\\\")]==[\\\"inter\\\",\\\"large\\\",\\\"shadow\\\",\\\"strong\\\",\\\"light\\\",\\\"strong\\\"],\\\"Current subtitle choices survive reload\\\")\\n check([saved[k] for k in (\\\"outline\\\",\\\"shadow\\\",\\\"boxOpacity\\\")]==[6,1.5,100],\\\"Current intensity values recomputed\\\")\\n check(saved[\\\"color\\\"]==\\\"#123456\\\" and saved[\\\"customColorSet\\\"] and [saved[k] for k in (\\\"outlineColor\\\",\\\"shadowColor\\\",\\\"boxColor\\\")]==[\\\"#abcdef\\\",\\\"#334455\\\",\\\"#556677\\\"],\\\"Current subtitle colors survive reload\\\")\\n check(prefs.evaluate(\\\"galleryVolumePreferences\\\")=={\\\"mode\\\":\\\"user\\\",\\\"preferred\\\":35,\\\"precision\\\":\\\"fine\\\"} and prefs.evaluate(\\\"playerSessionVolume\\\")==35,\\\"Current starting volume survives reload\\\")\\n check(prefs.evaluate(\\\"state.font\\\")==\\\"inter\\\" and prefs.evaluate(\\\"state.theme\\\")==\\\"glacier\\\",\\\"Current font and theme survive reload\\\")\\n prefs.evaluate(\\\"\\\"\\\"() => {\\n  localStorage.setItem('gallery.subtitlePreferences', JSON.stringify({font:'bad',size:44,effect:'bad',outlinePreset:'max',shadowPreset:'bad',boxPreset:'bad',colorMode:'bad',customColor:'invalid',customColorSet:'bad',outline:6,shadow:10,boxOpacity:100,background:'solid'}));\\n  localStorage.setItem('gallery.playback.startingVolume',JSON.stringify({mode:'fixed',preferred:20,precision:'bad'}));\\n  localStorage.setItem('gallery.font','bad');\\n  localStorage.setItem('gallery.softFuturistic.theme','paper');\\n }\\\"\\\"\\\")\\n invalid=prefs.evaluate(\\\"readSubtitlePrefs()\\\")\\n check(invalid==prefs.evaluate(\\\"SUBTITLE_DEFAULTS\\\"),\\\"Unsupported subtitle fields fall back to current defaults\\\")\\n check(prefs.evaluate(\\\"readGalleryVolumePreferences().mode\\\")==\\\"gallery\\\",\\\"Unsupported volume mode falls back to Gallery\\\")\\n check(prefs.evaluate(\\\"readGalleryFont()\\\")==\\\"system\\\" and prefs.evaluate(\\\"readSoftFuturisticTheme()\\\")==\\\"ocean\\\",\\\"Unsupported font and theme fall back\\\")\\n prefs.evaluate(\\\"\\\"\\\"() => {\\n  localStorage.removeItem('gallery.subtitlePreferences');\\n  localStorage.removeItem('gallery.font');\\n  localStorage.setItem('gallery.layoutExperimentA.subtitlePreview',JSON.stringify({size:'large'}));\\n  localStorage.setItem('gallery.layoutExperimentA.font','inter');\\n }\\\"\\\"\\\")\\n check(prefs.evaluate(\\\"readSubtitlePrefs()\\\")==prefs.evaluate(\\\"SUBTITLE_DEFAULTS\\\") and prefs.evaluate(\\\"readGalleryFont()\\\")==\\\"system\\\",\\\"Retired storage keys ignored\\\")\\n prefs.evaluate(\\\"localStorage.setItem('gallery.subtitlePreferences','{invalid')\\\")\\n check(prefs.evaluate(\\\"readSubtitlePrefs()\\\")==prefs.evaluate(\\\"SUBTITLE_DEFAULTS\\\"),\\\"Malformed subtitle storage uses defaults\\\")\\n prefs.close()\\n\"]")
assert t.count(a)==1
t=t.replace(a,b)
compile(t,str(tests),"exec")
tests.write_text(t,encoding="utf-8")
print("Updated HTML:",len(p.read_bytes()),hashlib.sha256(p.read_bytes()).hexdigest())
